import ast

# Check if Employee class is defined
tree = ast.parse(code)

class_nodes = [node for node in ast.walk(tree) if isinstance(node, ast.ClassDef)]
class_names = [cls.name for cls in class_nodes]

if 'Employee' not in class_names:
    raise AssertionError('Class Employee is not defined')

# Check for class variables
for node in class_nodes:
    if node.name == 'Employee':
        # Look for assignments in class body
        has_company = False
        has_count = False
        for item in node.body:
            if isinstance(item, ast.Assign):
                for target in item.targets:
                    if isinstance(target, ast.Name):
                        if target.id == 'company':
                            has_company = True
                        if target.id == 'employee_count':
                            has_count = True
        if not has_company:
            raise AssertionError('Employee class missing company class variable')
        if not has_count:
            raise AssertionError('Employee class missing employee_count class variable')
        break

print('TEST_PASSED')

